check.action:
Spawn subagent:
          - Backend: {phases.plan.backend}
          - Preset: {phases.plan.preset}
          - Prompt: [rendered plan prompt]
          - Log to: {state_dir}/iterations/{iteration:03d}-plan.log

Spawn subagent:
          - Backend: {phases.test.backend}
          - Preset: {phases.test.preset}
          - Prompt: [rendered test prompt]
          - Log to: {state_dir}/iterations/{iteration:03d}-test.log

Run tests to verify failure state:
          - Execute: {gates.tests.command}
          - Capture output to: {state_dir}/evidence/test-red-{iteration}.txt

Spawn quality gate subagent:
            - Backend: {phases.test.backend}
            - Prompt: tea-quality-gate.md with {{test_files}}, {{quality_threshold}}, {{task_description}}, {{story_acceptance_criteria}}
            - Log to: {state_dir}/evidence/tea-quality-{iteration}.json

step.action:
Spawn subagent:
        - Backend: {phases.implement.backend}
        - Preset: {phases.implement.preset}
        - Prompt: [rendered implement prompt]
        - Log to: {state_dir}/iterations/{iteration:03d}-implement.log

Run tests to verify implementation:
        - Execute: {gates.tests.command}
        - Capture output to: {state_dir}/evidence/test-green-{iteration}.txt

check.action:
Spawn healing subagent:
            - Backend: {phases.implement.backend}
            - Preset: {phases.implement.preset}
            - Prompt: tea-healing-prompt.md with {{test_failure_output}}
            - Log to: {state_dir}/iterations/{iteration:03d}-impl-heal.log

Spawn subagent:
          - Backend: {phases.review.backend}
          - Preset: {phases.review.preset}
          - Prompt: [rendered review prompt]
          - Log to: {state_dir}/iterations/{iteration:03d}-review.log

loop.action:
Spawn subagent:
            - Backend: {phases.fix.backend}
            - Preset: {phases.fix.preset}
            - Prompt: [rendered fix prompt]
            - Log to: {state_dir}/iterations/{iteration:03d}-fix-{fix_attempts}.log

Run tests:
            - Execute: {gates.tests.command}
            - Capture output to: {state_dir}/evidence/test-fix-{iteration}-{fix_attempts}.txt

check.action:
Re-run tests once:
              - Execute: {gates.tests.command}
              - Capture output to: {state_dir}/evidence/test-fix-retry-{iteration}-{fix_attempts}.txt

Spawn healing subagent:
                - Backend: {phases.fix.backend}
                - Preset: {phases.fix.preset}
                - Prompt: tea-healing-prompt.md with {{test_failure_output}}
                - Log to: {state_dir}/iterations/{iteration:03d}-heal-{fix_attempts}.log

Re-run tests after healing:
                - Execute: {gates.tests.command}
                - Capture output to: {state_dir}/evidence/test-heal-{iteration}-{fix_attempts}.txt

step.action:
Append to PROGRESS.md:
        ```
        ### Iteration {iteration}: {task}
        - Commit: auto if enabled (see git log)
        - Phases: {phases_executed}
        - Cost: ${iteration_cost}
        - Time: {execution_time}
        ```

check.action:
Create commit message:
              ```
              {task}

              Ralph iteration {iteration}
              Session: {session_id}

              Co-Authored-By: Ralph Mode <noreply@anthropic.com>
              ```

Create commit message:
            ```
            {task}

            Ralph iteration {iteration}
            Session: {session_id}

            Co-Authored-By: Ralph Mode <noreply@anthropic.com>
            ```
